svg.script:
/* F10 (cross-format SVG document): the four station links are focusable. The script
   wires the LAST station's forward Tab to loop back to the FIRST station, and the
   first station's Shift+Tab to loop to the last. Forward Tab therefore cycles among
   the four stations forever and never crosses the <object> boundary back to the host
   page. Note: the host page's paragraph BEFORE the object tells users "Tab through
   the diagram, then Tab again to continue" — but that advice is FALSE; there is no
   extra Tab that exits. Advice present, plausible, and wrong. */
var stations = ['st-lakeside','st-millgate','st-harbour','st-university']
  .map(function(id){ return document.getElementById(id); });
var first = stations[0], last = stations[stations.length - 1];
last.addEventListener('keydown', function (e) {
  if (e.key === 'Tab' && !e.shiftKey) { e.preventDefault(); first.focus(); }
});
first.addEventListener('keydown', function (e) {
  if (e.key === 'Tab' && e.shiftKey) { e.preventDefault(); last.focus(); }
});
